+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.component.Key;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final MessageStore messageStore;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messagesGrid = new Grid<>();
+    private boolean resettingAfterSend;
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        setSpacing(true);
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        FormLayout form = new FormLayout();
+        form.add(name, email, phone, message, send);
+        form.setColspan(message, 2);
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+
+        name.addValueChangeListener(event -> fieldEdited());
+        email.addValueChangeListener(event -> fieldEdited());
+        phone.addValueChangeListener(event -> fieldEdited());
+        message.addValueChangeListener(event -> fieldEdited());
+
+        messagesGrid.addColumn(ContactMessage::name).setHeader("Name");
+        messagesGrid.addColumn(ContactMessage::message).setHeader("Message");
+        messagesGrid.setItems(messageStore.getMessages());
+        messagesGrid.setWidthFull();
+
+        add(form, new Span("Messages"), messagesGrid);
+    }
+
+    private void fieldEdited() {
+        if (!resettingAfterSend) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void sendMessage() {
+        clearValidation();
+
+        boolean valid = true;
+        if (isBlank(name.getValue())) {
+            name.setErrorMessage("Name is required");
+            name.setInvalid(true);
+            valid = false;
+        }
+
+        String emailValue = valueOrEmpty(email.getValue());
+        String phoneValue = valueOrEmpty(phone.getValue());
+        if (!emailValue.isBlank() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            email.setErrorMessage("Enter a valid e-mail address");
+            email.setInvalid(true);
+            valid = false;
+        } else if (emailValue.isBlank() && phoneValue.isBlank()) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            email.setInvalid(true);
+            valid = false;
+        }
+
+        String messageValue = valueOrEmpty(message.getValue());
+        if (messageValue.isBlank()) {
+            message.setErrorMessage("Message is required");
+            message.setInvalid(true);
+            valid = false;
+        } else if (messageValue.length() > 500) {
+            message.setErrorMessage("Message must be at most 500 characters");
+            message.setInvalid(true);
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(name.getValue(), emailValue, phoneValue, messageValue));
+        messagesGrid.setItems(messageStore.getMessages());
+        Notification notification = Notification.show("Message sent");
+        notification.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
+
+        resettingAfterSend = true;
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        resettingAfterSend = false;
+        send.setEnabled(false);
+    }
+
+    private void clearValidation() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private static boolean isBlank(String value) {
+        return value == null || value.isBlank();
+    }
+
+    private static String valueOrEmpty(String value) {
+        return value == null ? "" : value;
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Unsaved message");
+        dialog.add(new Span("You have unsent changes. Leave this page?"));
+
+        Button keepEditing = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        dialog.getFooter().add(new HorizontalLayout(keepEditing, discard));
+        dialog.open();
+    }
+
+    private boolean hasUnsavedInput() {
+        return hasValue(name.getValue()) || hasValue(email.getValue()) || hasValue(phone.getValue())
+                || hasValue(message.getValue());
+    }
+
+    private static boolean hasValue(String value) {
+        return value != null && !value.isEmpty();
+    }
+}
